<?phpnamespace app\api\service\business;use app\api\service\CommService;use app\common\model\business\MallDisease;use app\common\model\business\MallDiseaseCategory;use app\common\model\business\MallDiseaseHospital;class DiseaseService extends CommService{    public function __construct($param, $user_info)    {        parent::_initialize($param, $user_info);    }    public function getDiseaseCategoryList()    {        $categoryModel = new MallDiseaseCategory();        $this->data['disease_category_list'] = $categoryModel->getCategoriesByInitial();        return $this->data;    }    public function getDiseaseList()    {        $this->data['disease_list'] = MallDisease::where('category_id', $this->param['category_id'])->field('disease_id,category_id,name')->order('sort desc')->select();        return $this->data;    }    public function getHospitalList()    {        $this->data['hospital_list'] = MallDiseaseHospital::where('disease_id', $this->param['disease_id'])            ->withJoin(['hospital' => ['hospital_id', 'name', 'logo', 'address']])            ->select();        return $this->data;    }}